        if (null != atomicInteger) {
            atomicInteger.decrementAndGet();
        }
    }

    @Override
    public void recordTime(final String name, final String[] labelValues, final long duration) {
        LongAdder longAdder = HISTOGRAM_MAP.get(name);
        if (null != longAdder) {
            longAdder.add(duration);
        }
    }

