        result.setGovernanceConfig(new GovernanceConfiguration(new RegistryCenterConfiguration("Zookeeper", "test", EmbedTestingServer.getConnectionString(), null), true));
        return result;
    }

    private JobConfiguration mockJobConfigWithWorkflow() {
        JobConfiguration result = ResourceUtil.mockJobConfig();
        result.getHandleConfig().setWorkflowConfig(new WorkflowConfiguration("ds_0", "1"));
        return result;
    }
}

