public abstract class AbstractShardingSphereDataSourceForReadWriteSplittingTest extends AbstractSQLTest {

    private static ShardingSphereDataSource dataSource;

    private static final String CONFIG = "config/config-readwrite-splitting.yaml";

    private static final List<String> ACTUAL_DATA_SOURCE_NAMES = Arrays.asList("test_write_ds", "test_read_ds");

    @BeforeClass
    public static void initReadWriteSplittingDataSources() throws SQLException, IOException {
        if (null != dataSource) {
            return;
        }
        dataSource = (ShardingSphereDataSource) YamlShardingSphereDataSourceFactory.createDataSource(getDataSources(), getFile(CONFIG));
    }

    private static Map<String, DataSource> getDataSources() {
        return Maps.filterKeys(getActualDataSources(), ACTUAL_DATA_SOURCE_NAMES::contains);
    }

    private static File getFile(final String fileName) {
        return new File(Preconditions.checkNotNull(
                AbstractShardingSphereDataSourceForReadWriteSplittingTest.class.getClassLoader().getResource(fileName), "file resource `%s` must not be null.", fileName).getFile());
    }

    protected final ShardingSphereDataSource getReadWriteSplittingDataSource() {
        return dataSource;
    }

    @AfterClass
    public static void clear() throws Exception {
        if (null == dataSource) {
            return;
        }
        dataSource.close();
        dataSource = null;
    }
}

