    @Mock
    private ShardingRule shardingRule;

    private List<TableRule> mockTableRules(final List<List<String>> shards) {
        List<TableRule> result = new LinkedList<>();
        for (List<String> each : shards) {
            result.add(mockTableRule(each));
        }
        return result;
