        URL url = getClass().getClassLoader().getResource("yaml/shadow-rule.yaml");
        assertNotNull(url);
        YamlRootRuleConfigurations rootRuleConfigurations = YamlEngine.unmarshal(new File(url.getFile()), YamlRootRuleConfigurations.class);
